#include <print>

int main() {
    int choice = 2;

    switch (choice) {
        case 1:
            std::println("你选了 Python"); break;
        case 2:
            std::println("你选了 C++");
            // break; 注释掉它，看穿透现场
        case 3:
            std::println("你选了数学"); break;
        default:
            std::println("没有这个选项"); break;
    }
    // 这一次打了两行，你选了数学是顺路滑出来的

    return 0;
}

wrongs:
#include <print>
int main() {
    int choice = 2;
    switch (choice) {
        case 1: std::println("你选了 Python"); break;
        case 2: std::println("你选了 C++"); break;
        default: std::println("没有这个选项"); break;
    }
    return 0;
}
#include <print>
int main() {
    int choice = 3;
    switch (choice) {
        case 2: std::println("你选了 C++"); break;
        case 3: std::println("你选了数学"); break;
        default: std::println("没有这个选项"); break;
    }
    return 0;   // 每张牌都要 break
}

